#!/usr/bin/env python3
"""Plumbing proposal -> docs/plumbing/03-proposal.md (tables for review with Avihai)."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
P = json.load(open(os.path.join(ROOT, 'data/plumbing/proposal.json'), encoding='utf-8'))
H0 = json.load(open(os.path.join(ROOT, 'data/site/origin.json')))['H0']
rel = lambda H: f'{H - H0:+.2f}'
FL = {'ground': 'קרקע', 'first': "קומה א'", 'unit': 'מרתף', 'roof': 'גג', 'shaft': 'פיר'}
L = ['# הצעת תכנון – אינסטלציה (לאישור)', '',
     'נוצר ע"י `python3 tools/plumbing/propose.py` ו-`report_proposal.py`. **כל מה שכאן הוא הצעה**: מוצג במודל רק במצב "עם ההצעה" (שכבות → אינסטלציה), ודורש את אישורך ואחר כך את אישור היועץ. ערכים טיפוסיים (גבהים, קטרים, בידוד) מסומנים ב-`tools/plumbing/proposal-inputs.json`.', '',
     '## החלטות שעליהן ההצעה בנויה', '']
L += [f'- **{d["id"]}** ({d["date"]}): {d["text"]}' for d in P['decisions']]
L += ['', '## לא בהצעה – ממתין להחלטה', ''] + [f'- **{d["id"]}**: {d["text"]}' for d in P['pending']]
L += ['', '## 1. הזזת קולטנים מתוך הבטון', '', '| צ.א | חוצה במיקום של היועץ | הזזה | בצירי הבית (מזרח / צפון, ס"מ) | אחרי ההזזה | מרחק לקו קיר | ענפים שהוארכו |', '|---|---|---|---|---|---|---|']
for s in P['stackMoves']:
    if not s.get('pts3d'): continue
    L.append(f'| {s["stack"]} | {", ".join(s["clashesBefore"])} | {s["displacement_m"] * 100:.0f} ס"מ | {s["local_dxdy_m"][0] * 100:+.0f} / {s["local_dxdy_m"][1] * 100:+.0f} | '
             f'{"נקי" if not s["clashesAfter"] else ", ".join(s["clashesAfter"])} | {s["distToWall_m"] * 100:.0f} ס"מ | {len(s["connectors"])} |')
L += ['', 'החיפוש: המקום הפנוי הקרוב ביותר (רשת של 2 ס"מ, עד 90 ס"מ), עם מרווח 3 ס"מ מכל אלמנט בטון לכל גובה הקולטן, מחוץ לממ"ד ולפיר, 16 ס"מ לפחות מקולטן או צמ"ג אחר, ועם העדפה להישאר צמוד לקו קיר (להלבשה). '
      'הענפים של היועץ הוארכו אופקית אל המיקום החדש, באותו מפלס. **לבדוק:** הלבשה / קיר בכל מיקום (אדריכל), ושמיקום הקורות במודל הוא בקירוב (עד IFC).', '']
sh = P['shaft']
L += ['## 2. פיר אינסטלציה (החלטה D2)', '', f'- מידות נטו: {sh["local"][2] * 100:.0f}×{sh["local"][3] * 100:.0f} ס"מ, בין {rel(sh["bottom"])} ל-{rel(sh["top"])}, צמוד לפאה הצפונית של הממ"ד ומחוץ לו.',
      f'- בדיקת שלד: {"לא חוצה קירות, עמודים או קורות שבמודל" if not sh["clashes"] else ", ".join(sh["clashes"])}. תקרת הגג (K-41) עוד לא במודל – לבדוק בשלב 3ד.',
      '- בפיר: עולה מים קרים (ברז ראשי בגובה +0.30 בקומת הקרקע), עולה לקומה א\', ירידה למוני היחידות, אספקה חמה וקו סחרור מבודדים.',
      '- במרתף הפיר נוחת בחדר הרחצה של יחידה 2 שבסקיצה. הכיור של יחידה 2 הוזז לאורך הקיר.', '']
L += ['## 3. מחלקים', '', '| מחלק | קומה | יציאות מים קרים | יציאות מים חמים | הערה |', '|---|---|---|---|---|']
for m in P['manifolds']:
    L.append(f'| {m["title"]} | {FL[m["floor"]]} | {len(m["outlets"]["cold"])} | {"ממתין PD1" if m["hotPending"] else len(m["outlets"]["hot"])} | ברז כדורי לכל יציאה, ברז ראשי בכניסה |')
L += ['', '## 4. נקודות מים (גבהים טיפוסיים – לאישור)', '', '| קבועה | קומה | גובה מעל הריצוף | PEX | קרים | חמים |', '|---|---|---|---|---|---|']
for p in P['points']:
    L.append(f'| {p["title"]} – {p["fixture"]} | {FL[p["floor"]]} | {p["H_rel"]:.2f} | ø{p["D_mm"]} | {"✓" if p["cold"] else ""} | {"✓" if p["hot"] else ("ממתין PD1" if p["hotPending"] else "")} |')
runs = P['runs']
L += ['', '## 5. צנרת', '', f'- {len(runs)} קטעים, סה"כ {sum(r["length_m"] for r in runs):.0f} מ\' PEX. כל צינור בשרוול מריכף לכל אורכו (הערה 10). אספקה חמה וחזרה – בבידוד {next(r["insulation_mm"] for r in runs if r.get("insulation_mm"))} מ"מ (זמני).',
      f'- הקטע הארוך ביותר ממחלק לנקודה: {max(r["length_m"] for r in runs if r["from"].startswith("MAN-") and r["to"] != "RET-RISER"):.1f} מ\' (הערה 3 בפרט הסחרור: עד 15 מ\') ✓',
      '- תוואי: בצירי הבית בלבד (בלי אלכסונים), קווים מקבילים בצרור במרווח 5 ס"מ, בתוך מילוי הרצפה (‎−0.07 מתחת לריצוף), סביב קירות ובפתחים. מעבר בבטון אסור; הממ"ד אסור בקרקע. עלייה בקיר לכל נקודה.', '',
      '| קטע | מערכת | קומה | קוטר | אורך | מ → אל |', '|---|---|---|---|---|---|']
SYS = {'cold': 'קרים', 'hot': 'חמים', 'return': 'סחרור'}
for r in runs:
    if not r['from'].startswith('MAN-'): L.append(f'| {r["id"]} | {SYS[r["system"]]} | {FL[r["floor"]]} | ø{r["D_mm"]} | {r["length_m"]:.1f} | {r["from"]} → {r["to"]} |')
L += ['', f'(ועוד {sum(1 for r in runs if r["from"].startswith("MAN-"))} קווים ממחלקים לנקודות – בטבלה בממשק, בלחיצה על כל קו.)', '']
L += ['## 6. שרוולים ומעברים', '', '| # | מעבר | קומה | צינור | שרוול | ITM / רום |', '|---|---|---|---|---|---|']
for i, s in enumerate(P['sleeves'], 1):
    L.append(f'| {i} | {s["through"]} | {FL.get(s["floor"], s["floor"])} | {s["pipe"]} | {s["sleeve"]} | {s["at"][0]:.2f} / {s["at"][1]:.2f} · {rel(s["at"][2])} |')
L += ['', '## 7. מה מוחלף מתוכנית היועץ (מוסתר במצב "עם ההצעה")', '', ', '.join(f'`{x}`' for x in P['superseded']), '',
      'קווי המים של היועץ שנכנסו לקירות (סוף תכנון), העולה WJ23 שבתוך העמוד C8, קו המטבח מהחצר, הקו החם בגג למחלק הקודם, ו-6 הקולטנים במיקום הקודם.', '']
S = P.get('site')
if S:
    comp = lambda x: f'חוליות {"+".join(str(round(v * 100)) for v in x["rings_m"]) or "—"} · טבעות {"+".join(str(round(v * 100)) for v in x["adjust_m"]) or "—"}' + (f' · טיט {round(x["mortar_m"] * 100)}' if x['mortar_m'] >= 0.01 else '')
    L += ['## 8. הצעות בפיתוח (לא תלויות בהחלטות הפתוחות)', '',
          'נוצר ע"י `tools/plumbing/propose_site.py`. מי הגשם **לא** בהצעה – החלטה PR1 (בור החלחול סותר את דוח הקרקע, ראו open-issues).', '',
          '### 8.1 מכסה במפלס הפיתוח', '', '| שוחה | T.L יועץ | מפלסי פיתוח ליד השוחה | T.L מוצע (טווח) | הרכב לפי היועץ | הרכב מוצע | הערה |', '|---|---|---|---|---|---|---|']
    for c in S['chamberRaise']:
        L.append(f'| {c["id"]} ø{round(c["D_m"] * 100)} | {c["TLfrom"]:.2f} | {", ".join(f"{h:.2f} ({d:.1f} מ\')" for h, d in c["finish"]["spots"])} | {c["TLto"]:.2f} ({c["finish"]["lo"]:.2f}–{c["finish"]["hi"]:.2f}) | '
                 f'{comp(c["before"])} | {comp(c["after"])} | {"בתוך התקרה התלויה " + c["slab"] + " – פתח בתקרה" if c["slab"] else ""} |')
    L += ['', 'הגובה הסופי – לפי הריצוף בפועל (לכן טבעות הגבהה). מפלסי הכניסות והיציאה לא משתנים.', '',
          '### 8.2 מפלים חיצוניים', '', '| קו | שוחה | קוטר | כניסה עליונה | כניסה תחתונה | מפל | ציר האנכי ממרכז השוחה | הערה |', '|---|---|---|---|---|---|---|---|']
    for d in S['drops']:
        L.append(f'| {d["run"]} | {d["chamber"]} | {d["material"]} ø{d["D_mm"]} | {d["ILin"]:.2f} | {d["ILlowInlet"]:.2f} | {d["drop_m"]:.2f} | {d["axisDist_m"]:.2f} | {d.get("note", "")}{" · מפלס כניסה זמני" if d["levelStatus"] == "provisional" else ""} |')
    L += ['', 'בכל מפל: הסתעפות מחוץ לשוחה, צינור אנכי בעטיפת בטון 10 ס"מ, 2×45° (הערה 4), כניסה בחוליה התחתונה (קידוח יהלום + אטם שוחה). ההמשך הישר נכנס לשוחה במפלס המקורי ונסגר בפקק ביקורת. '
          'הכניסה התחתונה של ø110 – בקודקודים אחידים עם היציאה ø160. שוחה 0 עירונית – הניפל לפי התאגיד, לא בהצעה.', '']
    h = S['hoseReel']
    L += ['### 8.3 גלגלון כיבוי אש', '', f'- {h["why"]}', f'- מיקום מוצע: {h["E"]:.2f} / {h["N"]:.2f}; הסתעפות מ-{h["tee"]["run"]} ב-{h["tee"]["E"]:.2f} / {h["tee"]["N"]:.2f}; PEX ø{h["D_mm"]}.',
          f'- הרכב: {" → ".join(h["components"])}.', f'- גבהים (זמני): ברזים {h["valveH_m"]:.2f}, מרכז הגלגלון {h["reelH_m"]:.2f} מעל הפיתוח.' + (f' העלייה עוברת בתקרה {h["slab"]} – שרוול ø50 יצוק.' if h['slab'] else ''), '']
    m = S['meter']
    L += ['### 8.4 חיבור מערכת המדידה', '', f'- {m["why"]}', f'- קצה ההכנה: {m["utwSource"]}.',
          '- בתצוגת היועץ: מערכת המדידה מוצגת עכשיו לפי הפרט (גומחה 80 ס"מ, ציר המונה 0.60 מעל הקרקע, עולים בשרוול PVC ø4"). קודם הוצגה בטעות מתחת לקרקע.', '']
UH = P.get('unitHot')
if UH:
    L += ['## 9. מים חמים ליחידות המרתף (PD1 – לפי ההמלצה, אושר 07.11)', '',
          '| יחידה | דוד | אורך אספקה עד המחלק | ענף ארוך | סה"כ | סחרור (הערה 12: מעל 25 מ\') |', '|---|---|---|---|---|---|']
    for hh, lp in zip(UH['heaters'], UH['loops']):
        L.append(f'| {"יחידה 1" if lp["unit"] == "unit1" else "יחידה 2"} | חשמלי {hh["volume_l"]} ל\' בגג ({hh["E"]:.2f} / {hh["N"]:.2f}) | {lp["supply_m"]:.1f} | {lp["farthestBranch_m"]:.1f} | {lp["total_m"]:.1f} | {"כן – קו חזרה + משאבה עם טיימר" if lp["loop"] else "לא נדרש"} |')
    L += ['', f'- אספקה PEX ø20, חזרה ø16, בידוד {UH["insulation_mm"]} מ"מ (זמני). בפיר נוספו 4 מקומות; **הפיר הוגדל מ-35 ל-40 ס"מ** (בדיקת שלד – נקי).',
          '- נקודות המים החמים ביחידות ומחלקי היחידות כבר לא "ממתין להחלטה" – חוברו.', '']
FF = P.get('firstFloor')
if FF:
    L += ['## 10. ענפי ביוב בקומה א\' (PL3 – לפי ההמלצה, אושר 07.11)', '',
          '- **ענפי האסלות (ø110)** – יורדים דרך התקרה באסלה ונתלים מתחתיה (פרט "עטיפת בטון" של היועץ) עד הקולטן. לא עוברים מעל הממ"ד.',
          '- **ענפי ø50** (כיורים, מחסומי רצפה – מעל הממ"ד) – נשארים במילוי ומצטרפים לירידת האסלה מעל התקרה. בלי חדירה לתקרת הממ"ד.', '',
          '| קטע | קוטר | I.L התחלה → סוף | תקרה מונמכת בקרקע | כיסוי עד הריצוף |', '|---|---|---|---|---|']
    for r in FF['runs']:
        dc = f'{r["droppedCeiling_m"] * 100:.0f} ס"מ' if r.get('droppedCeiling_m') else ''
        cv = f'{r["coverToFinish_m"] * 100:.0f} ס"מ' if r.get('coverToFinish_m') is not None else ''
        L.append(f'| {r["id"]} | ø{r["D_mm"]} | {r["ILup"]:.3f} → {r["ILdown"]:.3f} | {dc} | {cv} |')
    L += [''] + [f'- {"✓" if c["ok"] else "✗"} {c["text"]}' for c in FF['checks']] + ['']
US = P.get('unitSewer')
if US:
    c = US['chamber']
    L += ['## 11. ביוב יחידות המרתף – תא שאיבה נפרד (PB6 – לפי ההמלצה, אושר 07.11)', '', f'- {c["why"]}', f'- משאבות: {c["pumps"]}.', f'- מכסה: {c["cover"]}.', '',
          '| קטע | קוטר | I.L התחלה → סוף | אורך | הערה |', '|---|---|---|---|---|']
    for r in US['runs']:
        il = f'{r["ILup"]:.3f} → {r["ILdown"]:.3f}' if r.get('ILup') is not None else '—'
        L.append(f'| {r["id"]} | {r["material"]} ø{r["D_mm"]} | {il} | {r["length_m"]:.1f} | {r["note"][:120]} |')
    L += [''] + [f'- {"✓" if x["ok"] else "✗"} {x["what"]}: {x["text"]}' for x in US['checks']] + ['']
RN = P.get('rain')
if RN:
    L += ['## 12. מי גשם – 3 חלופות להשוואה (PR1)', '', f'משותף: {RN["common"]}. בממשק: שכבות → אינסטלציה → "מי גשם (להשוואה)".', '',
          '| | חלופה 1 – בור היועץ | חלופה 2 – שוחת ניקוז בחזית | חלופה 3 – בור חדש רחוק |', '|---|---|---|---|']
    A = RN['alternatives']
    rowsx = [('אורך צנרת', lambda a: f'{a["length_m"]:.1f} מ\''), ('ירידות דרך תקרה', lambda a: str(a['slabDrops'])), ('שרוולים בקורות יסוד', lambda a: str(a['beamSleeves'])),
             ('מרחק היעד מהיסודות (לבור: נדרש ≥3.0)', lambda a: f'{a["destination"]["distFoundations_m"]:.2f} מ\'' + (' – שוחה אטומה, בלי חלחול: הדרישה לא חלה' if a['destination']['kind'] == 'drainChamber' else '')), ('מרחק מגבול המגרש', lambda a: f'{a["destination"]["distBoundary_m"]:.2f} מ\''),
             ('רום כניסה ליעד', lambda a: f'{a["destination"]["IL"]:.2f}'), ('חציות קווים קיימים', lambda a: f'{len(a["crossings"])}' + (f' (⚠️ {len(a["tightCrossings"])} לתיאום גבהים: ' + ', '.join(x['with'] for x in a['tightCrossings']) + ')' if a['tightCrossings'] else '')),
             ('אישור נדרש', lambda a: a['approval'])]
    for nm, f in rowsx: L.append(f'| {nm} | ' + ' | '.join(f(a) for a in A) + ' |')
    L += ['', '- בכל החלופות: הבור / השוחה ø60; בבור – חצץ בשק גאוטכני (דוח הקרקע 11.6); עומק 3.0 מ\' זמני (לא כתוב בשום מקור).',
          '- חלופה 2: היציאה מהשוחה לגבול מסתיימת בפקק "חיבור לניקוז העירוני" – מיקום ורום החיבור לפי העירייה (לא הומצא).', '']
open(os.path.join(ROOT, 'docs/plumbing/03-proposal.md'), 'w', encoding='utf-8').write('\n'.join(L) + '\n')
print('ok', len(L))
